mapper.select:
SELECT p.id preId, p.prescriber_name prescriberName, d.dept_name deptName FROM comm_company_prescriber p LEFT JOIN comm_company cc ON cc.company_id = p.company_id LEFT JOIN comm_dept d ON p.dept_id = d.dept_id WHERE p.company_id =#{companyId}
and p.dept_id=#{deptId}
order by d.dept_name desc,p.prescriber_name asc
